30	const PROCESSING_FEE = 5;
31	
32	/**
33	 * The spec keeps intermediate amounts as exact fractions and rounds only the
34	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
35	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
36	 *
37	 * So percentages are applied as integer rationals — multiply by the numerator
38	 * first, divide by the denominator last — and money is carried in hundredths
39	 * of a G. Both operands of every product stay integral, so no drift accrues.
40	 */
41	const SUBUNITS_PER_G = 100;
42	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
43	
44	/** A percentage as an exact rational, e.g. +10 % is { num: 110, den: 100 }. */
45	interface Rate {
46	  num: number;
47	  den: number;
48	}
49	
50	/** Rates are deltas: the surcharge or discount itself, not the multiplied total. */
51	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
52	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
53	
54	const applyRate = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;
55	
56	/** Premiums round up — in the MHPCO's favour. */
57	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
58	
59	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
69	
70	const COMPONENT_TYPES = ["rune", "moonstone"];
71	
72	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
73	
74	/** Exactly this many alike components form a block, priced as one unit. */
75	const COMPONENT_BLOCK_SIZE = 3;
76	const COMPONENT_BLOCK_PREMIUM = 60;
77	
78	/** Splits items into those matching the predicate and those that do not. */
79	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
80	  items.filter(matches),
81	  items.filter((item) => !matches(item)),
82	];
83	
84	const groupByType = (items: Item[]): Map<string, Item[]> => {
85	  const groups = new Map<string, Item[]>();
86	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
87	
88	  return groups;
89	};
90	
91	const sumOfBasePremiums = (items: Item[]): number =>
92	  items.reduce((total, item) => total + basePremiumOf(item), 0);
93	
94	/**
95	 * Alike components — those of the very same type — form a block when there are
96	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
97	 * Any other count is priced per component.
98	 */
99	const componentGroupPremium = (group: Item[]): number =>
100	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
101	
102	/**
103	 * The policy base premium: every insured item's base premium, summed — except
104	 * that each group of alike components is priced as blocks where it can be.
105	 */
106	const policyBasePremiumOf = (items: Item[]): number => {
107	  const [components, mainItems] = partition(items, isComponent);
108	  const componentsTotal = [...groupByType(components).values()].reduce(
109	    (total, group) => total + componentGroupPremium(group),
110	    0,
111	  );
112	
113	  return sumOfBasePremiums(mainItems) + componentsTotal;
114	};
115	
116	/**
117	 * Item-specific surcharges apply to the affected item's own base premium.
118	 */
119	const itemSurchargesOf = (items: Item[]): number =>
120	  items.reduce(
121	    (total, item) =>
122	      total + (item.cursed ? applyRate(toSubunits(basePremiumOf(item)), CURSE_SURCHARGE) : 0),
123	    0,
124	  );
125	
126	/**
127	 * Modifiers are additive amounts, each computed against its own base: item
128	 * surcharges against the affected item, policy-wide modifiers against the
129	 * policy base premium. The processing fee is added at the very end.
130	 */
131	const quotePremium = (items: Item[]): number => {
132	  const policyBase = toSubunits(policyBasePremiumOf(items));
133	  const policyModifiers = applyRate(policyBase, FIRST_INSURANCE_SURCHARGE);
134	
135	  return toPremiumGold(
136	    policyBase + itemSurchargesOf(items) + policyModifiers + toSubunits(PROCESSING_FEE),
137	  );
138	};
139	
140	export const runScenario = (scenario: Scenario): ScenarioResults => {
141	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
142	};
