/** A percentage as an exact rational, e.g. +10 % is { num: 110, den: 100 }. */
interface Rate {
  num: number;
  den: number;
}

/** Rates are deltas: the surcharge or discount itself, not the multiplied total. */
const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };

const applyRate = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;

